);

const PaymentMethod = ({
  amount,
  centered = false,
}: {
  amount?: string;
  centered?: boolean;
}) => {
  if (!amount) {
    return <CardMethod />;
  }
  return (
    <Section
      align={centered ? "center" : undefined}
      style={{
        margin: centered ? "0 auto" : undefined,
        width: centered ? undefined : "100%",
      }}
    >
      <Fragment>
        <Row>
          <Column>
            <CardMethod />
          </Column>
          {centered ? (
            <Column
              style={{
                fontFamily,
                fontSize: "12px",
                lineHeight: "16px",
                padding: "0 12px",
              }}
            >
              |
            </Column>
          ) : null}
          <Column
            style={{
              color: "#4b5563",
              fontFamily,
              fontSize: "12px",
              fontWeight: 500,
              lineHeight: "16px",
              textAlign: "right",
            }}
          >
            {amount}
          </Column>
        </Row>
      </Fragment>
    </Section>
  );
};

const alignmentStyles = (alignment: OrderSummaryAlignment) => {
  if (alignment === "left") {
    return {
      amountAlign: "left" as const,
      amountWidth: undefined,
      labelAlign: "left" as const,
      labelWidth: "96px",
    };
  }
  if (alignment === "right") {
    return {
      amountAlign: "right" as const,
      amountWidth: "96px",
      labelAlign: "right" as const,
      labelWidth: undefined,
    };
  }
  if (alignment === "centered") {
    return {
      amountAlign: "left" as const,
      amountWidth: "50%",
      labelAlign: "right" as const,
      labelWidth: "50%",
    };
  }
  return {
    amountAlign: "right" as const,
    amountWidth: "50%",
    labelAlign: "left" as const,
    labelWidth: "50%",
  };
};

const SummaryRow = ({
  amount,
  alignment,
  label,
  padded,
  topPadded = false,
}: {
  amount: string;
  alignment: OrderSummaryAlignment;
  label: string;
  padded: boolean;
  topPadded?: boolean;
}) => {
  const styles = alignmentStyles(alignment);
  return (
    <Row>
      <Column
        style={{
          paddingLeft: padded ? "12px" : undefined,
          paddingTop: topPadded ? "12px" : undefined,
          textAlign: styles.labelAlign,
          width: styles.labelWidth,
        }}
      >
        {label}
      </Column>
      <Column style={{ width: "16px" }}>&zwj;</Column>
      <Column
        style={{
          paddingRight: padded ? "12px" : undefined,
          paddingTop: topPadded ? "12px" : undefined,
          textAlign: styles.amountAlign,
          width: styles.amountWidth,
        }}
