      <SummaryRow
        alignment={alignment}
        amount="$5.99"
        label="Tax"
        padded={boxed}
      />
      <Row>
        <Column colSpan={3} style={{ lineHeight: "16px" }}>
          &zwj;
        </Column>
      </Row>
      <SummaryRow
        alignment={alignment}
        amount="FREE"
        label="Shipping"
        padded={boxed}
      />
    </>
  );
  return (
    <EmailShell>
      <Section
        style={{
          backgroundColor: boxed && filled ? "#f9fafb" : undefined,
          borderRadius: boxed && filled ? "4px" : undefined,
          color: "#4b5563",
          fontFamily,
          fontSize: "16px",
          fontWeight: 500,
          lineHeight: "24px",
          tableLayout: "fixed",
          width: "100%",
        }}
      >
        <Fragment>
          {(() => {
            if (totalPosition === "top") {
              return (
                <>
                  <TotalRow
                    alignment={alignment}
                    boxed={boxed}
                    connected={filled}
                    large={cardDetails && !boxed}
                    position="top"
                  />
                  {boxed ? (
                    <Row>
                      <Column colSpan={3} style={{ lineHeight: "16px" }}>
                        &zwj;
                      </Column>
                    </Row>
                  ) : (
                    <Row>
                      <Column colSpan={3}>
                        <Divider />
                      </Column>
                    </Row>
                  )}
                </>
              );
            }
            return null;
          })()}
          {summaryRows}
          {(() => {
            if (totalPosition === "bottom") {
              return (
                <>
                  {boxed ? (
                    <Row>
                      <Column colSpan={3} style={{ lineHeight: "16px" }}>
                        &zwj;
                      </Column>
                    </Row>
                  ) : (
                    <Row>
                      <Column colSpan={3}>
                        <Divider />
                      </Column>
                    </Row>
                  )}
                  <TotalRow
                    alignment={alignment}
                    boxed={boxed}
                    connected={filled}
                    large={cardDetails && !boxed}
                    position="bottom"
                  />
                </>
              );
            }
            return null;
          })()}
          {(() => {
            if (cardDetails) {
              return (
                <Row>
                  <Column
                    colSpan={3}
                    style={{
                      backgroundColor: boxed ? "#fffffe" : undefined,
                      padding: boxed ? "0 12px" : 0,
                    }}
                  >
                    {boxed ? (
                      <Section style={{ lineHeight: "16px" }}>&zwj;</Section>
                    ) : (
                      <Divider margin={16} />
                    )}
                    <Text
                      style={{
                        ...textStyle,
                        color: "#030712",
                        fontSize: "14px",
                        fontWeight: 600,
                        lineHeight: "20px",
                        marginBottom: "8px",
                        textAlign:
                          alignment === "centered" ? "center" : undefined,
                      }}
                    >
                      Amount charged
                    </Text>
                    <PaymentMethod
                      amount="$35.98"
                      centered={alignment === "centered"}
                    />
                  </Column>
                </Row>
              );
            }
            return null;
          })()}
        </Fragment>
      </Section>
    </EmailShell>
  );
};

